mongodb:createCollection.mongodb:options:
{
   validator: {
        $jsonSchema: {
            bsonType: "object",
            required: ["id", "order_id", "user_id", "status", "timestamp", "payment_amount"],
            properties: {
                id: {
                      bsonType: "int",
                      description: "Unique identifier for payment"
                },
                order_id: {
                      bsonType: "int",
                      description: "Associated order ID"
                },
                user_id: {
                     bsonType: "int",
                     description: "Associated user ID"
                },
                status: {
                     bsonType: "string",
                     description: "Payment status"
                },
                timestamp: {
                     bsonType: "date",
                     description: "Payment timestamp"
                },
                payment_amount: {
                     bsonType: "double",
                     description: "Amount paid"
                }
            }
      }
   },
   validationAction: "warn",
   validationLevel: "strict"
}
